INSERT INTO llx_website_page(rowid, fk_page, fk_website, pageurl, aliasalt, title, description, lang, image, keywords, status, date_creation, tms, import_key, grabbed_from, type_container, htmlheader, content, author_alias, allowed_in_frames) VALUES(2__+MAX_llx_website_page__, null, 1, 'footer', '', 'Footer', '', 'fr', '', '', '1', '2019-08-15 16:42:44', '2020-06-19 10:18:14', null, '', 'page', '', '				<!-- Footer -->\n                    <footer id=\"footer\">\n						<section contenteditable=\"true\">\n							<h2>Aliquam sed mauris</h2>\n							<p>Sed lorem ipsum dolor sit amet et nullam consequat feugiat consequat magna adipiscing tempus etiam dolore veroeros. eget dapibus mauris. Cras aliquet, nisl ut viverra sollicitudin, ligula erat egestas velit, vitae tincidunt odio.</p>\n							<ul class=\"actions\">\n								<li><a href=\"generic.php\" class=\"buttonwebsite\">Learn More</a></li>\n							</ul>\n						</section>\n						<section contenteditable=\"true\">\n							<h2>Etiam feugiat</h2>\n							<dl class=\"alt\">\n								<dt>Address</dt>\n								<dd><?php echo $mysoc->getFullAddress(1, \'<br>\'); ?></dd>\n								<dt>Phone</dt>\n								<dd><?php echo $mysoc->phone; ?></dd>\n								<dt>Email</dt>\n								<dd><a href=\"mailto:<?php echo $mysoc->email; ?>\"><?php echo $mysoc->email; ?></a></dd>\n							</dl>\n							<ul class=\"icons\">\n	                          <ul class=\"list-inline\">\n                              <?php foreach($mysoc->socialnetworks as $key => $value) {\n                                print \'<li><a target=\"_blank\" class=\"icon alt fab fa-\'.$key.\'\" href=\"\'.(preg_match(\'/^http/\', $value) ? $value : \'https://www.\'.$key.\'.com/\'.$value).\'\"><span class=\"label\">\'.ucfirst($key).\'</span></a></li>\';\n                              } ?>\n                            </ul>\n						</section>\n						<div class=\"copyright\">&copy; Untitled. Design: <a href=\"https://html5up.net\">HTML5 UP</a> adapted for <a href=\"https://www.dolibarr.org\">Dolibarr</a> by <a href=\"https://www.dolicloud.com\">DoliCloud</a>.</div>\n					</footer>\n\n\n<script>\n// When the user scrolls down 20px from the top of the document, show the button\nwindow.onscroll = function() {scrollFunction()};\n\nfunction scrollFunction() {\n  console.log(\"Execute code for scroll Top button\");\n  if (document.body.scrollTop > 20 || document.documentElement.scrollTop > 20) {\n    document.getElementById(\"myBtnToTop\").style.display = \"block\";\n  } else {\n    document.getElementById(\"myBtnToTop\").style.display = \"none\";\n  }\n}\n\n// When the user clicks on the button, scroll to the top of the document\nfunction topFunction() {\n  document.body.scrollTop = 0; // For Safari\n  document.documentElement.scrollTop = 0; // For Chrome, Firefox, IE and Opera\n}\n</script>\n\n<button onclick=\"topFunction()\" id=\"myBtnToTop\" title=\"Go to top\">Top</button>\n', '', 0);

